# classify.star — deterministic signature matching over failed jobs.
# TAP transform contract (mirrors the platform's Starlark sandbox convention):
# step params arrive as predeclared globals (jobs, signatures, cap); the value
# assigned to `result` is the step's output. No I/O, no imports — Starlark is
# sandboxed by construction; the runtime enforces step/time ceilings.

def _match(job, sigs):
    for s in sigs:
        if job["failure_reason"] in s["failure_reason"]:
            if "stage_any" not in s or job["stage"] in s["stage_any"]:
                return s
    return None

def _classify(jobs, sigs, cap):
    failed = [j for j in jobs if j["status"] == "failed" and not j["allow_failure"]][:cap]
    classified = []
    unclassified = []
    for j in failed:
        s = _match(j, sigs)
        if s:
            classified.append({
                "name": j["name"],
                "stage": j["stage"],
                "failure_reason": j["failure_reason"],
                "category": s["category"],
                "evidence": s["name"],
                "confidence": s["confidence"],
                "classified_by": "signature",
                "web_url": j.get("web_url"),
            })
        else:
            unclassified.append({
                "name": j["name"],
                "stage": j["stage"],
                "failure_reason": j["failure_reason"],
                "allow_failure": j["allow_failure"],
            })
    return {
        "classified": classified,
        "unclassified": unclassified,
        "has_unclassified": len(unclassified) > 0,
    }

result = _classify(jobs, signatures, cap)
